//! The question set of a bench: generated by the harness from the user's RAW transcripts
//! (never from graphersal-memory's own summaries, which would favour the graph arm), with a
//! reference answer and the ids of the turns it comes from, kept per project in
//! `<data dir>/bench/questions/<project slug>.json`, which the user can edit and confirms.

use std::path::{Path, PathBuf};
use std::time::{Duration, SystemTime};

use serde_json::{Value, json};

use crate::fsutil;
use crate::transcript::{self, clip};

/// The categories of questions, in report order.
pub const CATEGORIES: [&str; 3] = ["rule", "decision", "history"];

/// The format version of a question file.
const FORMAT: u64 = 1;

/// The excerpt's budget (characters) for the generation prompt.
pub const EXCERPT_BUDGET: usize = 120_000;

/// One session's share of the excerpt at most (characters), so several sessions fit.
const SESSION_BUDGET: usize = 30_000;

/// A transcript changed more recently than this is still being written: left out, as the
/// session indexing leaves it out.
const RECENT: Duration = Duration::from_secs(30 * 60);

/// One question with its reference answer.
#[derive(Debug, Clone, PartialEq)]
pub struct Question {
    /// `Q1`, `Q2`, ...
    pub id: String,
    /// `rule`, `decision` or `history`.
    pub category: String,
    /// The question as the developer would ask it.
    pub question: String,
    /// The reference answer.
    pub reference: String,
    /// The turn ids (`turn:<session uuid>:<n>`) the reference comes from.
    pub sources: Vec<String>,
    /// The start of each source turn's prompt, to check the reference against.
    pub excerpts: Vec<String>,
    /// Whether the question is used (the user sets `false` to drop one).
    pub keep: bool,
}

/// The question set of one project.
#[derive(Debug, Clone, PartialEq)]
pub struct QuestionSet {
    /// The project key.
    pub project: String,
    /// When it was generated (UTC).
    pub generated_at: String,
    /// How many sessions the excerpt held.
    pub sessions: usize,
    /// What the generation cost (USD, as the harness reported it).
    pub cost_usd: f64,
    /// Whether the user confirmed it.
    pub confirmed: bool,
    /// The questions.
    pub questions: Vec<Question>,
}

impl QuestionSet {
    /// The questions in use (`keep`).
    pub fn kept(&self) -> Vec<&Question> {
        self.questions.iter().filter(|q| q.keep).collect()
    }

    /// The set as the JSON of its file.
    pub fn to_json(&self) -> Value {
        json!({
            "version": FORMAT,
            "project": self.project,
            "generated_at": self.generated_at,
            "sessions": self.sessions,
            "cost_usd": self.cost_usd,
            "confirmed": self.confirmed,
            "how_to_review": "Check each reference against its source turns. Fix a reference \
                in place, set \"keep\": false to drop a question, then run \
                `graphersal-memory bench questions --review` (or set \"confirmed\": true).",
            "questions": self.questions.iter().map(|q| json!({
                "id": q.id, "category": q.category, "question": q.question,
                "reference": q.reference, "sources": q.sources, "excerpts": q.excerpts,
                "keep": q.keep,
            })).collect::<Vec<_>>(),
        })
    }

    /// The set from the JSON of its file.
    pub fn from_json(value: &Value) -> Result<Self, String> {
        if value["version"].as_u64() != Some(FORMAT) {
            return Err("unsupported question file version".to_string());
        }
        let strings = |v: &Value| -> Vec<String> {
            v.as_array()
                .into_iter()
                .flatten()
                .filter_map(|s| s.as_str().map(str::to_string))
                .collect()
        };
        let mut questions = Vec::new();
        for (i, q) in value["questions"]
            .as_array()
            .into_iter()
            .flatten()
            .enumerate()
        {
            let text = |key: &str| q[key].as_str().unwrap_or_default().trim().to_string();
            let question = Question {
                id: q["id"]
                    .as_str()
                    .map_or_else(|| format!("Q{}", i + 1), str::to_string),
                category: text("category"),
                question: text("question"),
                reference: text("reference"),
                sources: strings(&q["sources"]),
                excerpts: strings(&q["excerpts"]),
                keep: q["keep"].as_bool().unwrap_or(true),
            };
            if !CATEGORIES.contains(&question.category.as_str()) {
                return Err(format!(
                    "question {}: category '{}' is not one of {}",
                    question.id,
                    question.category,
                    CATEGORIES.join(", ")
                ));
            }
            if question.question.is_empty() || question.reference.is_empty() {
                return Err(format!(
                    "question {}: the question or its reference is empty",
                    question.id
                ));
            }
            questions.push(question);
        }
        Ok(Self {
            project: value["project"].as_str().unwrap_or_default().to_string(),
            generated_at: value["generated_at"]
                .as_str()
                .unwrap_or_default()
                .to_string(),
            sessions: value["sessions"].as_u64().unwrap_or(0) as usize,
            cost_usd: value["cost_usd"].as_f64().unwrap_or(0.0),
            confirmed: value["confirmed"].as_bool().unwrap_or(false),
            questions,
        })
    }

    /// Reads the set of `project` (none yet: `None`).
    pub fn load(data_dir: &Path, project: &str) -> Result<Option<Self>, String> {
        let path = path(data_dir, project);
        let Some(bytes) = fsutil::read_optional(&path)? else {
            return Ok(None);
        };
        let value: Value = serde_json::from_slice(&bytes)
            .map_err(|err| format!("{} is not valid JSON: {err}", path.display()))?;
        Self::from_json(&value)
            .map(Some)
            .map_err(|err| format!("{}: {err}", path.display()))
    }

    /// Writes the set to `file`.
    pub fn save_to(&self, file: &Path) -> Result<(), String> {
        if let Some(dir) = file.parent() {
            std::fs::create_dir_all(dir)
                .map_err(|err| format!("cannot create {}: {err}", dir.display()))?;
        }
        fsutil::write_atomic(
            file,
            format!(
                "{}\n",
                crate::jsonedit::render(&self.to_json(), Some("  "), 0)
            )
            .as_bytes(),
        )
    }
}

/// The question file of `project`.
pub fn path(data_dir: &Path, project: &str) -> PathBuf {
    data_dir
        .join("bench")
        .join("questions")
        .join(format!("{}.json", crate::import::claude_slug(project)))
}

/// The finished transcripts of `project` in Claude Code's `projects` directory (its directory
/// is named after the project's path), newest first.
pub fn transcripts(projects_dir: &Path, project: &str, now: SystemTime) -> Vec<PathBuf> {
    let dir = projects_dir.join(crate::import::claude_slug(project));
    let Ok(entries) = std::fs::read_dir(&dir) else {
        return Vec::new();
    };
    let mut files: Vec<(SystemTime, PathBuf)> = entries
        .filter_map(Result::ok)
        .map(|entry| entry.path())
        .filter(|p| p.is_file() && p.extension().is_some_and(|ext| ext == "jsonl"))
        .filter_map(|p| {
            let modified = std::fs::metadata(&p).ok()?.modified().ok()?;
            let age = now.duration_since(modified).unwrap_or_default();
            (age >= RECENT).then_some((modified, p))
        })
        .collect();
    files.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| a.1.cmp(&b.1)));
    files.into_iter().map(|(_, p)| p).collect()
}

/// The raw-transcript excerpt the questions are generated from: newest sessions first, each
/// turn marked with its id, until `budget` characters; also the start of each turn's prompt by
/// id (the source excerpts of the question file).
#[derive(Debug, Clone, Default)]
pub struct Excerpt {
    /// The text.
    pub text: String,
    /// `(turn id, start of the prompt)` of every turn in the text.
    pub turns: Vec<(String, String)>,
    /// How many sessions it holds.
    pub sessions: usize,
}

impl Excerpt {
    /// The excerpt of `files` (newest first).
    pub fn of(files: &[PathBuf], budget: usize) -> Self {
        let mut out = Self::default();
        for file in files {
            let Ok(bytes) = std::fs::read(file) else {
                continue;
            };
            let uuid = file
                .file_stem()
                .map(|s| s.to_string_lossy().to_string())
                .unwrap_or_default();
            let parsed = transcript::parse(&bytes, &uuid);
            if parsed.turns.len() < 2 {
                continue;
            }
            let mut text = format!(
                "\n===== session {uuid} ({} to {}): {}\n",
                parsed.started_at.chars().take(16).collect::<String>(),
                parsed.ended_at.chars().take(16).collect::<String>(),
                clip(&parsed.title, 200)
            );
            let mut turns = Vec::new();
            for turn in &parsed.turns {
                let id = format!("turn:{uuid}:{}", turn.n);
                let piece = format!(
                    "\n[{id}] USER: {}\nASSISTANT: {}\n",
                    clip(&turn.user, 1_200),
                    clip(&turn.assistant, 600)
                );
                if text.len() + piece.len() > SESSION_BUDGET {
                    break;
                }
                text.push_str(&piece);
                turns.push((id, clip(&turn.user, 300)));
            }
            if out.text.len() + text.len() > budget {
                break;
            }
            out.text.push_str(&text);
            out.turns.extend(turns);
            out.sessions += 1;
        }
        out
    }

    fn excerpt_of(&self, id: &str) -> Option<&str> {
        self.turns
            .iter()
            .find(|(turn, _)| turn == id)
            .map(|(_, text)| text.as_str())
    }
}

/// The JSON schema of the generator's answer.
pub fn schema() -> Value {
    json!({
        "type": "object",
        "properties": {"questions": {"type": "array", "items": {"type": "object", "properties": {
            "category": {"type": "string", "enum": CATEGORIES},
            "question": {"type": "string"},
            "reference": {"type": "string"},
            "sources": {"type": "array", "items": {"type": "string"}},
        }, "required": ["category", "question", "reference", "sources"]}}},
        "required": ["questions"],
    })
}

/// The generation prompt: `count` questions about `project` from `excerpt`.
pub fn prompt(project: &str, count: usize, excerpt: &Excerpt) -> String {
    let name = Path::new(project)
        .file_name()
        .map(|n| n.to_string_lossy().to_string())
        .unwrap_or_else(|| project.to_string());
    format!(
        "You write benchmark questions that test whether an AI coding assistant remembers \
earlier working sessions with a developer on the project \"{name}\". Below are excerpts of the \
raw session transcripts; every turn starts with its id in brackets, like [turn:<session>:<n>].

Write exactly {count} questions, about a third in each category:
- rule: a standing instruction the developer gave (how to work, what never to do, a convention);
- decision: a choice the developer made, with its reason;
- history: what happened in one session (a bug found and its cause, a result, a number, what was \
released or left open).

Each question:
- question: self-contained, as the developer would ask it weeks later; it must not contain the \
answer, a session id or a turn id;
- reference: the correct answer in 1-3 English sentences, with the concrete facts (names, \
versions, numbers) the transcript states; only facts the developer stated or confirmed, or that \
the transcript clearly establishes; never a guess;
- sources: the ids of the turns that support the reference (one or more, exactly as written).

Prefer facts a future session would need. Write in English whatever the transcript's language. \
Answer with one JSON object matching this JSON schema:
{}

The transcripts follow.
{}",
        schema(),
        excerpt.text
    )
}

/// The questions of a generator's answer (`structured_output`, or JSON in `result`): those
/// with a known category, a question, a reference and at least one source among the excerpt's
/// turns (unknown source ids are dropped), at most `count`, numbered `Q1`...
pub fn parse(answer: &Value, excerpt: &Excerpt, count: usize) -> Result<Vec<Question>, String> {
    let output = if answer["structured_output"].is_object() {
        answer["structured_output"].clone()
    } else if let Some(result) = answer["result"].as_str() {
        crate::bench::json_in(result).ok_or("the generator answered no JSON")?
    } else {
        answer.clone()
    };
    let mut out = Vec::new();
    for item in output["questions"].as_array().into_iter().flatten() {
        let text = |key: &str| item[key].as_str().unwrap_or_default().trim().to_string();
        let category = text("category");
        let (question, reference) = (text("question"), text("reference"));
        if !CATEGORIES.contains(&category.as_str()) || question.is_empty() || reference.is_empty() {
            continue;
        }
        let mut sources = Vec::new();
        let mut excerpts = Vec::new();
        for id in item["sources"].as_array().into_iter().flatten() {
            let Some(id) = id.as_str().map(|s| s.trim().trim_matches(['[', ']'])) else {
                continue;
            };
            if let Some(start) = excerpt.excerpt_of(id)
                && !sources.iter().any(|s| s == id)
            {
                sources.push(id.to_string());
                excerpts.push(start.to_string());
            }
        }
        if sources.is_empty() {
            continue;
        }
        out.push(Question {
            id: format!("Q{}", out.len() + 1),
            category,
            question,
            reference,
            sources,
            excerpts,
            keep: true,
        });
        if out.len() == count {
            break;
        }
    }
    if out.is_empty() {
        return Err(
            "the generator answered no usable question (each needs a category, a \
                    question, a reference and a source turn of the excerpt)"
                .to_string(),
        );
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn excerpt() -> Excerpt {
        Excerpt {
            text: "[turn:s1:0] USER: never push\n".into(),
            turns: vec![
                ("turn:s1:0".into(), "never push".into()),
                ("turn:s1:1".into(), "why lz4".into()),
            ],
            sessions: 1,
        }
    }

    #[test]
    fn generated_questions_keep_only_grounded_ones() {
        let answer = json!({"total_cost_usd": 0.1, "structured_output": {"questions": [
            {"category": "rule", "question": "May I push?", "reference": "No.",
             "sources": ["turn:s1:0", "turn:nope:3", "turn:s1:0"]},
            {"category": "decision", "question": "Why lz4?", "reference": "Speed.",
             "sources": ["[turn:s1:1]"]},
            {"category": "history", "question": "Ungrounded?", "reference": "x",
             "sources": ["turn:other:1"]},
            {"category": "gossip", "question": "q", "reference": "r", "sources": ["turn:s1:0"]},
            {"category": "rule", "question": "", "reference": "r", "sources": ["turn:s1:0"]},
        ]}});
        let questions = parse(&answer, &excerpt(), 10).unwrap();
        assert_eq!(questions.len(), 2);
        assert_eq!(questions[0].id, "Q1");
        assert_eq!(questions[0].sources, ["turn:s1:0"]);
        assert_eq!(questions[0].excerpts, ["never push"]);
        assert_eq!(questions[1].sources, ["turn:s1:1"]);
        assert_eq!(parse(&answer, &excerpt(), 1).unwrap().len(), 1);
        // JSON inside the result text, as a model may answer.
        let in_result = json!({"result": format!("```json\n{}\n```",
            json!({"questions": [{"category": "rule", "question": "q", "reference": "r",
                                  "sources": ["turn:s1:0"]}]}))});
        assert_eq!(parse(&in_result, &excerpt(), 5).unwrap().len(), 1);
        assert!(parse(&json!({"result": "sorry"}), &excerpt(), 5).is_err());
    }

    #[test]
    fn a_question_set_round_trips_and_an_edit_is_validated() {
        let dir = crate::mcp_tests::TempDir::new("qset");
        let set = QuestionSet {
            project: "/w/p".into(),
            generated_at: "2026-11-10T00:00:00Z".into(),
            sessions: 2,
            cost_usd: 0.2,
            confirmed: false,
            questions: parse(
                &json!({"questions": [{"category": "rule", "question": "q", "reference": "r",
                                      "sources": ["turn:s1:0"]}]}),
                &excerpt(),
                5,
            )
            .unwrap(),
        };
        let file = path(dir.path(), "/w/p");
        set.save_to(&file).unwrap();
        assert!(
            file.ends_with("bench/questions/-w-p.json"),
            "{}",
            file.display()
        );
        let loaded = QuestionSet::load(dir.path(), "/w/p").unwrap().unwrap();
        assert_eq!(loaded, set);
        assert_eq!(QuestionSet::load(dir.path(), "/w/other").unwrap(), None);
        let mut edited = set.to_json();
        edited["questions"][0]["category"] = json!("trivia");
        assert!(QuestionSet::from_json(&edited).is_err());
        edited["questions"][0]["category"] = json!("rule");
        edited["questions"][0]["keep"] = json!(false);
        assert!(QuestionSet::from_json(&edited).unwrap().kept().is_empty());
    }

    #[test]
    fn the_excerpt_marks_turn_ids_and_respects_its_budget() {
        let dir = crate::mcp_tests::TempDir::new("excerpt");
        let file = dir.path().join("0f0e0d0c-aaaa.jsonl");
        std::fs::write(&file, transcript::tests::fixture()).unwrap();
        let excerpt = Excerpt::of(std::slice::from_ref(&file), EXCERPT_BUDGET);
        assert_eq!(excerpt.sessions, 1);
        assert!(
            excerpt.text.contains("[turn:0f0e0d0c-aaaa:0] USER:"),
            "{}",
            excerpt.text
        );
        assert!(!excerpt.turns.is_empty());
        let tiny = Excerpt::of(&[file], 10);
        assert_eq!(tiny.sessions, 0);
        assert!(tiny.text.is_empty());
        let prompt = prompt("/w/app", 6, &excerpt);
        assert!(prompt.contains("project \"app\""));
        assert!(prompt.contains("exactly 6 questions"));
    }

    #[test]
    fn only_finished_transcripts_of_the_project_are_taken_newest_first() {
        let dir = crate::mcp_tests::TempDir::new("transcripts");
        let project_dir = dir.path().join("-w-p");
        std::fs::create_dir_all(&project_dir).unwrap();
        for name in ["a.jsonl", "b.jsonl", "notes.txt"] {
            std::fs::write(project_dir.join(name), "{}").unwrap();
        }
        std::fs::create_dir_all(dir.path().join("-w-other")).unwrap();
        std::fs::write(dir.path().join("-w-other").join("c.jsonl"), "{}").unwrap();
        let now = SystemTime::now();
        assert!(
            transcripts(dir.path(), "/w/p", now).is_empty(),
            "too recent"
        );
        let later = now + Duration::from_secs(3600);
        let found = transcripts(dir.path(), "/w/p", later);
        assert_eq!(found.len(), 2);
        assert!(found.iter().all(|f| f.starts_with(&project_dir)));
    }
}
